import test from 'node:test';
import assert from 'node:assert/strict';
import {generatePreset, rebuildIntegerComponent, machineReport, instancePlanes, normalizeTransform, validateComponent, validateMesh, planesEquivalent, componentPreview, signedVolume} from '../src/index.js';
const near=(a,b,e=1e-8)=>assert.ok(Math.abs(a-b)<e,`${a} != ${b}`);
for(const part of ['crown','pavilion'])for(const scale of [1,1.25,1.6])test(`explicit ${part} reconstruction at XY ${scale}: integer, bounded, no lost active faces`,()=>{const c=generatePreset({part}),t=normalizeTransform({translation:[0,0,part==='crown'?.12:-.12],scale:[scale,1,1]}),before=JSON.stringify({c,t}),r=rebuildIntegerComponent(c,t,96);assert.ok(r.report.safe);assert.ok(machineReport(instancePlanes(r.component,r.transform),96).exact);assert.equal(validateMesh(r.polys).valid,true);assert.equal(r.report.lostFaces.length,0);assert.equal(JSON.stringify({c,t}),before);assert.equal(r.transform.translation[2],t.translation[2]);assert.deepEqual(r.transform.scale,[1,1,1]);assert.equal(r.component.family,'custom');assert.equal(r.component.recipe,undefined);near(signedVolume(r.targetPolys),signedVolume(componentPreview(c))*scale);if(scale!==1){assert.ok(r.report.changedPlanes>0);assert.ok(r.report.maxPlaneResidual>0);assert.ok(r.report.topologyChanged);}else{assert.equal(r.report.changedPlanes,0);assert.ok(!r.report.topologyChanged);}});
test('repair is a preview candidate, not an in-place lossy transform',()=>{const c=generatePreset(),saved=JSON.stringify(c);const r=rebuildIntegerComponent(c,{scale:[1.25,1,1]},96);assert.equal(JSON.stringify(c),saved);assert.ok(c.recipe);assert.ok(!r.component.recipe);});
test('repair records provenance and survives schema validation without regeneration',()=>{const r=rebuildIntegerComponent(generatePreset(),{scale:[1.25,1,1]},96),c=validateComponent(JSON.parse(JSON.stringify(r.component)));assert.ok(planesEquivalent(c.planes,r.component.planes));assert.equal(c.reconstruction.teeth,96);assert.equal(c.provenance.type,'explicit-integer-reconstruction');});
test('repaired geometry is stable under a second integer projection',()=>{const a=rebuildIntegerComponent(generatePreset(),{scale:[1.3,.8,1.2]},96);const b=rebuildIntegerComponent(a.component,a.transform,96);assert.equal(b.report.changedPlanes,0);assert.ok(planesEquivalent(a.component.planes,b.component.planes));near(a.report.afterVolume,b.report.afterVolume);});
test('axis-violating input is never repaired by silently discarding displacement',()=>{assert.throws(()=>rebuildIntegerComponent(generatePreset(),{translation:[.1,0,0]},96),/加工轴/);});
test('coarse tooth projection with lost facets is explicitly unsafe',()=>{const r=rebuildIntegerComponent(generatePreset(),{scale:[1.4,1,1]},4);assert.ok(!r.report.safe);assert.ok(r.report.lostFaces.length>0);});
test('unbounded half component cannot become an apparently valid repair',()=>{const c=generatePreset();c.planes=[{id:'table',n:[0,0,1],d:.5,part:'crown',role:'table'}];assert.throws(()=>rebuildIntegerComponent(c,{},96),/未闭合/);});
test('known numeric audit for 1.25x crown stretch is not presented as exact meets',()=>{const r=rebuildIntegerComponent(generatePreset(),{scale:[1.25,1,1]},96).report;assert.equal(r.changedPlanes,28);near(r.maxAzimuthDeltaDeg,1.8735840312379182,1e-7);assert.ok(r.maxPlaneResidual>.006);assert.ok(Math.abs(r.afterSize[1]-r.beforeSize[1])>.016);assert.ok(r.topologyChanged);});
